<?php /** The depletion runs (screen depletion-run-list). Data: rows, total, page, f, seesCost, tz */ ?>
<?= view('shared/header.php', ['id' => 'depletion-run-list', 'title' => 'Depletion runs', 'crumbs' => [['Home', '/'], ['Sales by day', '/sales/'], ['Depletion runs', null]]]) ?>
<div class="main-content" id="depletion-run-list-content">
    <form method="get" action="/sales/runs/" class="card mb-3" id="run-filters" hx-get="/sales/runs/" hx-target="#page-content" hx-push-url="true"><div class="card-body d-flex flex-wrap gap-2 align-items-center">
        <select name="status" class="form-select btn-touch w-auto" id="run-filter-status" aria-label="Status"><option value="">Every status</option><?php foreach (['done', 'partial', 'void'] as $s): ?><option value="<?= $s ?>" <?= $f['status'] === $s ? 'selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select>
        <input type="date" name="from" class="form-control btn-touch w-auto" value="<?= e($f['from']) ?>" aria-label="From"><input type="date" name="to" class="form-control btn-touch w-auto" value="<?= e($f['to']) ?>" aria-label="To"><button type="submit" class="btn btn-light-brand btn-touch">Filter</button></div></form>
    <?php if ($rows === []): ?><div class="card"><div class="card-body text-muted fs-12" id="run-list-empty">No run yet.</div></div><?php else: ?>
    <div class="card"><div class="card-body p-0"><div class="table-responsive"><table class="table table-sm mb-0 fs-12" id="runs-table"><thead><tr><th>Day</th><th>Status</th><th class="text-end">Run</th><th class="text-end">Lines</th><th class="text-end">Depleted</th><th class="text-end">Unmapped</th><th class="text-end">Voided</th><th class="text-end">Mods unmapped</th><th class="text-end">Ingredients</th><th class="text-end">Value</th><th>Started</th><th>By</th></tr></thead><tbody>
    <?php foreach ($rows as $r): $id = (int) $r['depletion_run_id']; ?><tr id="run-row-<?= $id ?>"><td><?= hx_link('/sales/runs/' . $id, e(format_date((string) $r['business_date']))) ?></td><td><span class="badge <?= pos_chip($r['status']) ?>"><?= e($r['status']) ?></span></td><td class="text-end"><?= (int) $r['run_no'] ?></td><td class="text-end"><?= (int) $r['lines_total'] ?></td><td class="text-end"><?= (int) $r['lines_depleted'] ?></td><td class="text-end"><?= (int) $r['lines_unmapped'] ?></td><td class="text-end"><?= (int) $r['lines_voided'] ?></td><td class="text-end"><?= (int) $r['modifiers_unmapped'] ?></td><td class="text-end"><?= (int) $r['ingredients'] ?></td>
        <td class="text-end"><?= money($seesCost && $r['value'] !== null ? (string) $r['value'] : null) ?></td><td><?= e(format_ts((string) $r['started_at'], $tz)) ?></td><td><?= e($r['started_by'] === null ? 'worker' : (string) $r['started_by_name']) ?></td></tr><?php endforeach; ?>
    </tbody></table></div></div></div>
    <?php if ($total > POS_PAGE): ?><div class="d-flex justify-content-between mt-2"><span class="fs-12 text-muted"><?= $total ?> runs</span><div class="btn-group"><?php if ($page > 1): ?><?= hx_link('/sales/runs/?' . http_build_query(['page' => $page - 1] + array_filter($f)), 'Previous', 'btn btn-light btn-touch') ?><?php endif; ?><?php if ($page * POS_PAGE < $total): ?><?= hx_link('/sales/runs/?' . http_build_query(['page' => $page + 1] + array_filter($f)), 'Next', 'btn btn-light btn-touch') ?><?php endif; ?></div></div><?php endif; ?>
    <?php endif; ?>
</div>
